    value = aliases.get(value, value)
    if value in {EXPERIMENT_MANUAL, *EXPERIMENT_CHOICES}:
        return value
    raise ValueError(f"Unsupported experiment line: {line}. Expected one of {EXPERIMENT_CHOICES}.")


